/*
 * SAI — The Space Between
 * A seven-room generative sanctuary. No network calls, trackers, libraries, or storage.
 * All art is drawn live in Canvas2D. Sounds are generated by Web Audio after consent.
 */
(() => {
  'use strict';

  const TAU = Math.PI * 2;
  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
  const lerp = (a, b, t) => a + (b - a) * t;
  const ease = t => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
  const $ = id => document.getElementById(id);
  const canvas = $('world');
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) {
    $('chapterDescription').textContent = '현재 브라우저는 Canvas를 지원하지 않습니다. 최신 브라우저에서 열어주세요.';
    return;
  }

  const roomData = [
    { name: '숨', en: 'BREATH / THE FIRST MOMENT', title: '당신이 숨 쉬는 동안,<br><em>우주도 숨을 쉽니다.</em>', desc: '아무것도 증명하지 않아도 됩니다.<br>단 한 번의 숨으로, 이 순간에 도착하세요.', poem: '존재는 언제나 충분히 작은 기적입니다.', eyebrow: 'A SMALL ACT OF BEING', hint: '화면을 터치하거나 버튼을 눌러, 작은 숨결을 보내보세요.', symbol: '◌', ascii: 'INHALE / EXHALE' },
    { name: '시간', en: 'TIME / THE LONG NOW', title: '시간은 흐르지만,<br><em>지금은 늘 여기 있습니다.</em>', desc: '같은 일 초도 마음에 따라 다르게 펼쳐집니다.<br>시간의 속도를 바꾸며, 그 사이를 바라보세요.', poem: '서두르지 않는 순간에도, 우리는 도착하고 있습니다.', eyebrow: 'BEND THE SENSE OF TIME', hint: '슬라이더로 시간을 느리게 또는 빠르게. 정지 버튼으로 잠시 멈출 수 있습니다.', symbol: '⌛', ascii: 'NOTHING IS LATE' },
    { name: '생명', en: 'LIFE / A GRAMMAR OF GROWTH', title: '하나의 씨앗에는<br><em>아직 없는 숲이 있습니다.</em>', desc: '생명은 완성된 모양이 아니라<br>끝없이 다른 모습이 되는 과정인지 모릅니다.', poem: '한 번의 선택이, 수없이 많은 가지가 됩니다.', eyebrow: 'PLANT A POSSIBILITY', hint: '빛이 흐르는 공간을 터치해 보세요. 씨앗마다 다른 나무가 자랍니다.', symbol: '✾', ascii: 'EVERYTHING BECOMES' },
    { name: '인식', en: 'PERCEPTION / THE OBSERVER', title: '보이는 것이 전부라면,<br><em>보이지 않는 것은 무엇일까요.</em>', desc: '시선을 옮길 때마다 다른 세계가 드러납니다.<br>세상이 달라진 걸까요, 보는 방식이 달라진 걸까요?', poem: '우리가 보지 못한 것은, 반드시 없는 것이 아닙니다.', eyebrow: 'LOOK AT THE UNSEEN', hint: '화면 위에서 손가락이나 마우스를 움직이세요. 관점을 뒤집어 볼 수도 있습니다.', symbol: '◉', ascii: 'THE ACT OF SEEING' },
    { name: '연결', en: 'CONNECTION / INVISIBLE THREADS', title: '서로 멀리 있는 것들도<br><em>하나의 하늘 안에 있습니다.</em>', desc: '닿지 않는 것처럼 보이던 별들 사이에<br>손끝으로 조용한 길을 그어보세요.', poem: '관계는 거리를 지우는 것이 아니라, 건너가는 일입니다.', eyebrow: 'WEAVE A CONSTELLATION', hint: '두 별을 차례로 선택하세요. 또는 버튼으로 뜻밖의 인연을 만드세요.', symbol: '⋈', ascii: 'NO STAR IS ALONE' },
    { name: '비움', en: 'RELEASE / LET THE LIGHT GO', title: '붙잡지 않아도<br><em>사라지지 않는 것들이 있습니다.</em>', desc: '오늘의 걱정이나 마음속 문장 하나를 적어보세요.<br>그것은 잠시 빛이 되었다가, 하늘로 돌아갑니다.', poem: '놓아준다는 것은, 없었던 일로 만드는 것이 아닙니다.', eyebrow: 'A PRIVATE RITUAL OF RELEASE', hint: '입력 내용은 저장·전송되지 않습니다. 이 화면에서만 빛이 되어 사라집니다.', symbol: '✧', ascii: 'GENTLY LET GO' },
    { name: '귀환', en: 'RETURN / THE UNFINISHED YOU', title: '당신은 처음과 같지만,<br><em>완전히 같지는 않습니다.</em>', desc: '지나온 선택들이 모여, 오직 지금의 작은 우주가 됩니다.<br>아무것도 남기지 않아도 괜찮습니다.', poem: '우리는 끝에 도착하는 대신, 다시 시작할 수 있습니다.', eyebrow: 'AN UNREPEATABLE UNIVERSE', hint: '지금까지 남긴 빛의 흔적을 한 장의 이미지로 보관할 수 있습니다.', symbol: '∞', ascii: 'BEGIN AGAIN' }
  ];
  const quotes = [
    ['숨이 깊어질수록, 기다리던 고요가 가까워집니다.', '당신의 호흡은 이미 이 세계에 작은 파동을 남겼습니다.', '지금의 당신에게 필요한 속도는 당신만이 압니다.'],
    ['느린 시간이 곧 잃어버린 시간은 아닙니다.', '멈춤 역시 시간의 한 형태입니다.', '영원은 아주 짧은 순간의 다른 이름일지 모릅니다.'],
    ['같은 씨앗도 다른 우주를 꿈꿉니다.', '자란다는 것은 더 많은 방향을 허락하는 일입니다.', '길을 몰라도 생명은 앞으로 나아갑니다.'],
    ['시선이 닿는 자리에서 숨은 무늬가 나타납니다.', '하나의 세계에, 여러 개의 관점이 공존합니다.', '익숙한 것은 낯선 것의 오래된 얼굴입니다.'],
    ['두 점 사이에 새로운 이야기가 생겼습니다.', '멀리 있다는 것은 관계가 없다는 뜻이 아닙니다.', '가장 조용한 빛도 다른 빛에 닿습니다.'],
    ['지금은 그저, 놓아주어도 괜찮습니다.', '사라지는 것은 모양이지, 지나온 의미가 아닐지 모릅니다.', '마음에도 여백이 필요합니다.'],
    ['어느 순간도 똑같이 다시 오지는 않습니다.', '다음 숨부터, 또 다른 우주가 시작됩니다.', '귀환은 끝이 아니라 새로운 시선입니다.']
  ];

  const randomSeed = (() => {
    try { const a = new Uint32Array(1); crypto.getRandomValues(a); return a[0] || 239113; }
    catch { return (Math.random() * 4294967295) >>> 0; }
  })();
  function makeRng(seed) {
    let s = seed >>> 0;
    return function () {
      s += 0x6D2B79F5;
      let x = s;
      x = Math.imul(x ^ (x >>> 15), x | 1);
      x ^= x + Math.imul(x ^ (x >>> 7), x | 61);
      return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
    };
  }
  const rng = makeRng(randomSeed);
  const nightSky = Array.from({ length: 260 }, (_, i) => ({ x: rng(), y: rng(), r: .35 + rng() * 1.55, a: .18 + rng() * .63, tw: .3 + rng() * 1.9, phase: rng() * TAU, tint: i % 7 }));
  const waterDust = Array.from({ length: 600 }, () => ({ a: rng() * TAU, ring: .11 + rng() * .91, phase: rng() * TAU, rate: .18 + rng() * .8, size: .3 + rng() * 1.3 }));
  const perceptionWords = ['경계', '가능성', '느낌', '너머', '기억', '존재', '찰나', '여백', '무한', '시선'];
  const nodes = Array.from({ length: 72 }, (_, i) => {
    const a = rng() * TAU;
    const r = Math.sqrt(rng()) * .93;
    return { x: Math.cos(a) * r, y: Math.sin(a) * r, z: rng(), size: rng() * 1.5 + .8, phase: rng() * TAU, id: i };
  });

  const state = {
    scene: 0, width: 0, height: 0, dpr: 1, t: 0, lastFrame: 0, elapsed: 0,
    pointer: { x: .68, y: .52, tx: .68, ty: .52, active: false },
    pulse: 0, breathCount: 0, seedCount: 0, focusCount: 0, linkCount: 0, releaseCount: 0,
    rate: 1, timePhase: 0, timePaused: false, inverted: false,
    plants: [], ripples: [], links: [], selectedNode: null, released: [], quoteCycle: Array(7).fill(0),
    sound: false, audio: null, prefersReduced: matchMedia('(prefers-reduced-motion: reduce)').matches,
    menuOpen: false, aboutOpen: false, toastTimer: null, actionCount: 0,
    sceneTransition: 0, lastScene: 0
  };

  const escapeAttr = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const action = (label, id, extras = '', arrow = true) => `<button type="button" class="action ${extras}" id="${id}">${label}${arrow ? '<span class="action-arrow" aria-hidden="true">↗</span>' : ''}</button>`;

  function controlsForScene() {
    let html = '';
    switch (state.scene) {
      case 0:
        html = action('숨결 보내기', 'breatheAction', 'emphasis') + action('다음 정원으로', 'startAction', 'subtle');
        break;
      case 1:
        html = `<label class="range-wrap" for="timeRate"><span class="range-title">시간의 감각</span><input id="timeRate" aria-label="시간의 속도" type="range" min="0" max="200" step="5" value="${Math.round(state.rate * 100)}"><span class="range-value" id="timeRateValue">${state.rate.toFixed(1)}×</span></label>`;
        html += action(state.timePaused ? '다시 흐르게' : '잠시 멈추기', 'timePause', 'subtle', false);
        break;
      case 2:
        html = action('씨앗 하나 심기', 'plantAction', 'emphasis') + action('새로운 빈 땅', 'clearPlants', 'subtle');
        break;
      case 3:
        html = action('관점 뒤집기', 'invertAction', 'emphasis') + action('다른 시선 찾기', 'moveFocus', 'subtle');
        break;
      case 4:
        html = action('뜻밖의 별 연결', 'linkAction', 'emphasis') + action('다시 흩어놓기', 'clearLinks', 'subtle');
        break;
      case 5:
        html = `<form class="release-form" id="releaseForm"><input type="text" id="releaseInput" maxlength="48" autocomplete="off" autocapitalize="sentences" spellcheck="false" aria-label="내려놓을 짧은 문장" placeholder="이곳에 놓아줄 한 문장을 적어주세요"><button type="submit" class="action emphasis">빛으로 보내기 <span class="action-arrow" aria-hidden="true">↗</span></button></form>`;
        break;
      case 6:
        html = action('나의 우주 이미지 저장', 'saveAction', 'emphasis') + action('다시 처음으로', 'restartAction', 'subtle');
        break;
    }
    $('sceneControls').innerHTML = html;
    switch (state.scene) {
      case 0:
        $('breatheAction').addEventListener('click', breathe);
        $('startAction').addEventListener('click', () => changeScene(1));
        break;
      case 1:
        $('timeRate').addEventListener('input', e => {
          state.rate = Number(e.target.value) / 100;
          $('timeRateValue').textContent = state.rate.toFixed(1) + '×';
          if (state.rate > 0) state.timePaused = false;
          $('timePause').textContent = state.timePaused ? '다시 흐르게' : '잠시 멈추기';
        });
        $('timePause').addEventListener('click', () => {
          state.timePaused = !state.timePaused;
          $('timePause').textContent = state.timePaused ? '다시 흐르게' : '잠시 멈추기';
          nextQuote();
          subtleSound(280);
        });
        break;
      case 2:
        $('plantAction').addEventListener('click', () => {
          plantSeed(.46 + rng() * .37, .68 + rng() * .18);
        });
        $('clearPlants').addEventListener('click', () => { state.plants = []; nextQuote(); showToast('새로운 가능성을 위한 자리를 비웠습니다.'); });
        break;
      case 3:
        $('invertAction').addEventListener('click', invertFocus);
        $('moveFocus').addEventListener('click', () => {
          state.pointer.tx = .37 + rng() * .51;
          state.pointer.ty = .23 + rng() * .54;
          state.pointer.active = true;
          state.focusCount++;
          state.actionCount++;
          addRipple(state.pointer.tx, state.pointer.ty, 1.5);
          nextQuote();
        });
        break;
      case 4:
        $('linkAction').addEventListener('click', connectRandom);
        $('clearLinks').addEventListener('click', () => { state.links = []; state.selectedNode = null; nextQuote(); showToast('별들은 여전히 같은 하늘에 있습니다.'); });
        break;
      case 5:
        $('releaseForm').addEventListener('submit', e => {
          e.preventDefault();
          const input = $('releaseInput');
          if (!input.value.trim()) { showToast('놓아줄 마음 한 조각을 적어주세요.'); input.focus(); return; }
          releaseText(input.value.trim().slice(0, 48));
          input.value = '';
          input.blur();
        });
        break;
      case 6:
        $('saveAction').addEventListener('click', savePostcard);
        $('restartAction').addEventListener('click', () => changeScene(0));
        break;
    }
  }

  let transitionSerial = 0;
  function changeScene(index) {
    index = clamp(index, 0, roomData.length - 1);
    if (state.scene === index && !state.menuOpen) return;
    state.lastScene = state.scene;
    state.scene = index;
    state.sceneTransition = 1;
    state.selectedNode = null;
    const serial = ++transitionSerial;
    const copy = document.querySelector('.stage-copy');
    const interaction = $('interactionArea');
    copy.classList.add('is-changing');
    interaction.classList.add('is-changing');
    const data = roomData[index];
    // All updates occur together; a short visual crossfade gives the words room to arrive.
    window.setTimeout(() => {
      if (serial !== transitionSerial) return;
      copy.classList.toggle('compact', index === 3 || index === 5);
      $('chapterIndex').textContent = `${String(index + 1).padStart(2, '0')} / 07`;
      $('chapterEn').textContent = data.en;
      $('chapterTitle').innerHTML = data.title; // static, author-controlled text only
      $('chapterDescription').innerHTML = data.desc; // static, author-controlled text only
      $('poemText').textContent = data.poem;
      $('interactionEyebrow').textContent = data.eyebrow;
      $('interactionHint').textContent = data.hint;
      $('sceneSymbol').textContent = data.symbol;
      $('sceneAscii').textContent = data.ascii;
      $('pageNum').innerHTML = `${String(index + 1).padStart(2, '0')} <i>/</i> 07`;
      $('prevBtn').disabled = index === 0;
      $('nextBtn').disabled = index === 6;
      controlsForScene();
      document.querySelectorAll('[data-scene]').forEach(btn => {
        const active = Number(btn.dataset.scene) === index;
        btn.classList.toggle('active', active);
        if (active) btn.setAttribute('aria-current', 'step'); else btn.removeAttribute('aria-current');
      });
      copy.classList.remove('is-changing');
      interaction.classList.remove('is-changing');
    }, 160);
    closeMenu();
    if (index === 2 && !state.plants.length) {
      // The room is already alive when first discovered. New seeds visibly grow from zero.
      [[.57, .82, 7300], [.75, .84, 5300], [.89, .78, 3000]].forEach(([x, y, age]) => {
        plantSeed(x, y, false);
        state.plants[state.plants.length - 1].start -= age;
      });
    }
    if (index === 3 && !state.pointer.active) {
      state.pointer.tx = .69; state.pointer.ty = .51;
    }
    if (index === 6) nextQuote(true);
    subtleSound(180 + index * 38);
  }

  function nextQuote(silent = false) {
    const s = state.scene;
    const msg = quotes[s][state.quoteCycle[s]++ % quotes[s].length];
    $('poemText').textContent = msg;
    if (!silent) state.actionCount++;
  }

  function showToast(message) {
    const toast = $('toast');
    toast.textContent = message;
    toast.classList.add('visible');
    clearTimeout(state.toastTimer);
    state.toastTimer = setTimeout(() => toast.classList.remove('visible'), 3100);
  }

  function breathe() {
    state.pulse = Math.min(2.5, state.pulse + 1.25);
    state.breathCount++;
    state.actionCount++;
    addRipple(.7, .51, 1.1);
    nextQuote();
    subtleSound(220);
  }
  function plantSeed(x, y, count = true) {
    x = clamp(x, .14, .95); y = clamp(y, .32, .94);
    if (state.plants.length >= 11) state.plants.shift();
    state.plants.push({ x, y, start: state.elapsed, kind: rng() * TAU, size: .64 + rng() * .5, tilt: (rng() - .5) * .55, hue: rng() });
    if (count) { state.seedCount++; state.actionCount++; nextQuote(); subtleSound(240 + rng() * 220); }
    addRipple(x, y, .8);
  }
  function invertFocus() {
    state.inverted = !state.inverted;
    state.focusCount++; state.actionCount++;
    addRipple(state.pointer.x, state.pointer.y, 1.4);
    nextQuote(); subtleSound(state.inverted ? 440 : 320);
  }
  function connectNodes(a, b) {
    if (a === b) return;
    if (state.links.some(e => (e.a === a && e.b === b) || (e.a === b && e.b === a))) {
      showToast('두 별은 이미 서로 이어져 있습니다.'); return;
    }
    if (state.links.length >= 36) state.links.shift();
    state.links.push({ a, b, start: state.elapsed });
    state.linkCount++; state.actionCount++; nextQuote();
    subtleSound(220 + rng() * 330);
    const n = nodes[b]; addRipple(.68 + n.x * .25, .52 + n.y * .39, .7);
  }
  function connectRandom() {
    let a = Math.floor(rng() * nodes.length), b = Math.floor(rng() * nodes.length);
    let tries = 0;
    while ((a === b || state.links.some(e => (e.a === a && e.b === b) || (e.a === b && e.b === a))) && tries++ < 80) {
      a = Math.floor(rng() * nodes.length); b = Math.floor(rng() * nodes.length);
    }
    connectNodes(a, b);
  }
  function addRipple(x, y, strength = 1) {
    state.ripples.push({ x, y, start: state.elapsed, strength });
    if (state.ripples.length > 25) state.ripples.shift();
  }

  function releaseText(text) {
    const off = document.createElement('canvas');
    off.width = 1050; off.height = 180;
    const pctx = off.getContext('2d', { willReadFrequently: true });
    if (!pctx) return;
    const fontSize = Math.min(68, 970 / Math.max(text.length, 2) * (/[가-힣]/.test(text) ? 1.65 : 2.35));
    pctx.fillStyle = '#ffffff';
    pctx.textBaseline = 'middle';
    pctx.textAlign = 'center';
    pctx.font = `400 ${fontSize}px "Noto Serif KR", "AppleMyungjo", "Batang", serif`;
    pctx.fillText(text, 525, 90, 1020);
    let pixels;
    try { pixels = pctx.getImageData(0, 0, off.width, off.height).data; }
    catch { showToast('이 브라우저에서는 문장 입자를 만들 수 없습니다.'); return; }
    const pts = [];
    for (let y = 0; y < 180; y += 4) for (let x = 0; x < 1050; x += 4) {
      if (pixels[(y * 1050 + x) * 4 + 3] > 90 && rng() > .23) {
        const relativeX = (x - 525) / 1050;
        const relativeY = (y - 90) / 180;
        pts.push({ x: .68 + relativeX * .57, y: .5 + relativeY * .17, vx: (rng() - .46) * .00012, vy: -(rng() * .00025 + .000045), size: .6 + rng() * 1.05, offset: rng() * 850, spin: (rng() - .5) * .003, phase: rng() * TAU });
      }
    }
    // Limit particle count for smooth mobile rendering without changing the effect.
    const stride = Math.max(1, Math.ceil(pts.length / 1000));
    const birth = state.elapsed;
    state.released = pts.filter((_, i) => i % stride === 0).map(p => ({ ...p, birth }));
    state.releaseCount++;
    state.actionCount++;
    state.pulse = 1.1;
    nextQuote();
    subtleSound(196);
    showToast('그 문장은 이곳에서만 빛으로 변하고, 남지 않습니다.');
  }

  function closeMenu() {
    state.menuOpen = false;
    $('mobileMenu').classList.remove('open');
    $('mobileMenu').setAttribute('aria-hidden', 'true');
    $('mobileMenu').inert = true;
    $('menuBtn').setAttribute('aria-expanded', 'false');
    $('menuBtn').setAttribute('aria-label', '장면 목록 열기');
  }
  function toggleMenu() {
    if (state.menuOpen) { closeMenu(); return; }
    state.menuOpen = true;
    $('mobileMenu').inert = false;
    $('mobileMenu').setAttribute('aria-hidden', 'false');
    $('mobileMenu').classList.add('open');
    $('menuBtn').setAttribute('aria-expanded', 'true');
    $('menuBtn').setAttribute('aria-label', '장면 목록 닫기');
  }
  function openAbout() {
    state.aboutOpen = true;
    $('aboutOverlay').hidden = false;
    $('aboutOverlay').querySelector('.about-dialog').focus();
  }
  function closeAbout() {
    state.aboutOpen = false;
    $('aboutOverlay').hidden = true;
    $('aboutBtn').focus();
  }

  // A wind-like oscillator bed, deliberately quiet. Nothing is recorded or streamed.
  function toggleSound() {
    if (state.sound) {
      state.sound = false;
      if (state.audio) state.audio.gain.gain.setTargetAtTime(0, state.audio.ctx.currentTime, .45);
    } else {
      try {
        if (!state.audio) {
          const AudioCtor = window.AudioContext || window.webkitAudioContext;
          if (!AudioCtor) throw new Error('Web Audio unavailable');
          const ac = new AudioCtor();
          const master = ac.createGain(); master.gain.value = 0;
          const filter = ac.createBiquadFilter(); filter.type = 'lowpass'; filter.frequency.value = 460;
          const compressor = ac.createDynamicsCompressor(); compressor.threshold.value = -26; compressor.ratio.value = 3;
          filter.connect(compressor); compressor.connect(master); master.connect(ac.destination);
          const osc = [110, 164.81, 220, 329.63].map((f, i) => {
            const o = ac.createOscillator(), g = ac.createGain();
            o.type = i % 2 ? 'sine' : 'triangle';
            o.frequency.value = f; o.detune.value = [0, -6, 4, 8][i];
            g.gain.value = [.09, .055, .05, .025][i];
            o.connect(g); g.connect(filter); o.start(); return o;
          });
          const lfo = ac.createOscillator(), lfoGain = ac.createGain();
          lfo.frequency.value = .085; lfoGain.gain.value = 70;
          lfo.connect(lfoGain); lfoGain.connect(filter.frequency); lfo.start();
          state.audio = { ctx: ac, gain: master, osc, lfo };
        }
        state.audio.ctx.resume();
        state.audio.gain.gain.setTargetAtTime(.37, state.audio.ctx.currentTime, 1.2);
        state.sound = true;
      } catch (err) { showToast('현재 브라우저에서는 소리를 재생할 수 없습니다.'); return; }
    }
    $('soundBtn').setAttribute('aria-pressed', String(state.sound));
    $('soundBtn').setAttribute('aria-label', state.sound ? '소리 끄기' : '소리 켜기');
    $('soundBtn').setAttribute('title', state.sound ? '소리 끄기' : '소리 켜기');
    showToast(state.sound ? '아주 작은 우주의 소리를 켰습니다.' : '소리를 끄고 고요로 돌아왔습니다.');
  }
  function subtleSound(freq = 220) {
    if (!state.sound || !state.audio) return;
    try {
      const ac = state.audio.ctx;
      const o = ac.createOscillator(), gain = ac.createGain(), filter = ac.createBiquadFilter();
      o.type = 'sine'; o.frequency.setValueAtTime(freq, ac.currentTime);
      o.frequency.exponentialRampToValueAtTime(freq * 1.33, ac.currentTime + 1.05);
      filter.type = 'lowpass'; filter.frequency.value = 880;
      gain.gain.setValueAtTime(.0001, ac.currentTime);
      gain.gain.exponentialRampToValueAtTime(.024, ac.currentTime + .045);
      gain.gain.exponentialRampToValueAtTime(.0001, ac.currentTime + 2.1);
      o.connect(filter); filter.connect(gain); gain.connect(state.audio.gain); o.start(); o.stop(ac.currentTime + 2.2);
    } catch { /* Audio is ornamental; graphics continue on failure. */ }
  }

  function savePostcard() {
    try {
      const c = document.createElement('canvas');
      c.width = 1600; c.height = 1100;
      const g = c.getContext('2d');
      if (!g) throw new Error('No 2D context');
      const bg = g.createLinearGradient(0, 0, 1600, 1100);
      bg.addColorStop(0, '#050b16'); bg.addColorStop(.59, '#0c1727'); bg.addColorStop(1, '#1a1828');
      g.fillStyle = bg; g.fillRect(0, 0, 1600, 1100);
      const rg = g.createRadialGradient(1020, 490, 50, 1020, 490, 690);
      rg.addColorStop(0, 'rgba(58,139,144,.24)'); rg.addColorStop(.55, 'rgba(64,85,115,.1)'); rg.addColorStop(1, 'rgba(0,0,0,0)');
      g.fillStyle = rg; g.fillRect(0, 0, 1600, 1100);
      const ps = makeRng(randomSeed ^ state.seedCount ^ (state.breathCount << 9) ^ (state.linkCount << 18));
      for (let i = 0; i < 650; i++) {
        const x = ps() * 1600, y = ps() * 1100;
        g.fillStyle = `rgba(${i % 4 ? '219,231,226' : '235,201,163'},${.09 + ps() * .37})`;
        g.beginPath(); g.arc(x, y, .3 + ps() * 1.3, 0, TAU); g.fill();
      }
      const px = 1050, py = 520;
      g.save(); g.translate(px, py); g.globalCompositeOperation = 'screen';
      for (let j = 0; j < 19; j++) {
        const angle = j * 2.39996 + (randomSeed % 300) / 100;
        const radius = 55 + j * 13 + (state.actionCount % 7) * 6;
        g.save(); g.rotate(angle);
        g.beginPath(); g.ellipse(0, 0, radius + 55, radius * (.14 + ps() * .5), ps() * .8, 0, TAU);
        g.strokeStyle = j % 3 === 0 ? 'rgba(238,199,150,.27)' : 'rgba(111,210,214,.17)';
        g.lineWidth = .75 + ps() * 1.6; g.stroke();
        g.restore();
      }
      for (let i = 0; i < 1600; i++) {
        const a = ps() * TAU, radius = Math.pow(ps(), .66) * 370;
        const x = Math.cos(a) * radius, y = Math.sin(a) * radius * .63;
        g.fillStyle = i % 6 ? `rgba(139,222,215,${.05 + ps() * .63})` : `rgba(243,206,166,${.1 + ps() * .72})`;
        g.beginPath(); g.arc(x, y, .32 + ps() * 1.35, 0, TAU); g.fill();
      }
      g.restore();
      g.strokeStyle = 'rgba(233,213,188,.36)'; g.lineWidth = 1;
      g.strokeRect(50, 50, 1500, 1000);
      g.fillStyle = '#eecfad'; g.font = '34px serif'; g.fillText('✳', 105, 132);
      g.font = '15px sans-serif'; g.letterSpacing = '6px'; g.fillText('S A I  —  THE SPACE BETWEEN', 163, 128);
      g.letterSpacing = '0px';
      g.fillStyle = '#f2eee6'; g.font = '400 76px "Noto Serif KR", "AppleMyungjo", "Batang", serif';
      g.fillText('오늘도,', 124, 420); g.fillText('당신은 하나의', 124, 527); g.fillText('우주였습니다.', 124, 634);
      g.fillStyle = '#e3c39c'; g.font = '23px "Noto Serif KR", "AppleMyungjo", "Batang", serif';
      g.fillText('변하지 않는 것은 없습니다. 사라진 것은 더더욱.', 126, 697);
      g.fillStyle = '#bbc5c8'; g.font = '18px sans-serif';
      const values = [
        `숨결 ${state.breathCount}`, `씨앗 ${state.seedCount}`, `인식의 변화 ${state.focusCount}`,
        `별의 연결 ${state.linkCount}`, `놓아준 문장 ${state.releaseCount}`
      ];
      values.forEach((v, i) => { g.fillText(v, 125 + (i % 2) * 260, 800 + Math.floor(i / 2) * 42); });
      g.fillStyle = '#a3b8ba'; g.font = '14px sans-serif'; g.letterSpacing = '3px';
      g.fillText('AN UNREPEATABLE MOMENT', 126, 983);
      g.textAlign = 'right'; g.fillText(new Date().toLocaleDateString('ko-KR', { year: 'numeric', month: 'long', day: 'numeric' }), 1490, 983);
      g.textAlign = 'left';
      const filename = `SAI_나의우주_${new Date().toISOString().slice(0, 10)}.png`;
      const download = blob => {
        if (!blob) throw new Error('Failed to create PNG');
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href = url; a.download = filename;
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 2500);
        showToast('당신의 우주가 한 장의 이미지로 남았습니다.');
      };
      if (c.toBlob) c.toBlob(download, 'image/png');
      else { const a = document.createElement('a'); a.href = c.toDataURL('image/png'); a.download = filename; a.click(); showToast('우주 이미지가 저장되었습니다.'); }
    } catch (err) { console.error('Postcard export:', err); showToast('이미지를 만들지 못했습니다. 다른 브라우저에서 시도해 주세요.'); }
  }

  function sizeWorld() {
    state.width = Math.max(1, window.innerWidth);
    state.height = Math.max(1, window.innerHeight);
    state.dpr = Math.min(window.devicePixelRatio || 1, state.width < 800 ? 1.65 : 1.8);
    canvas.width = Math.round(state.width * state.dpr);
    canvas.height = Math.round(state.height * state.dpr);
    canvas.style.width = `${state.width}px`;
    canvas.style.height = `${state.height}px`;
    ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
  }
  const H = () => state.height, W = () => state.width;
  function visualCenter() {
    return { x: W() * (W() < 800 ? .57 : .684), y: H() * (W() < 800 ? .54 : .505), r: Math.min(H() * (W() < 800 ? .29 : .38), W() * (W() < 800 ? .39 : .295)) };
  }
  function fillCircle(x, y, r, color) {
    ctx.beginPath(); ctx.arc(x, y, Math.max(r, .05), 0, TAU); ctx.fillStyle = color; ctx.fill();
  }
  function radialGlow(x, y, r, colorStops) {
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    for (const [stop, color] of colorStops) g.addColorStop(stop, color);
    ctx.fillStyle = g; ctx.fillRect(x - r, y - r, 2 * r, 2 * r);
  }
  function strokeCurve(points, stroke, lineWidth = 1) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth; ctx.stroke();
  }
  function drawEnvironment(t) {
    const w = W(), h = H();
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#050911'; ctx.fillRect(0, 0, w, h);
    // Nebulous light is different in each room, but the horizon stays recognizably one world.
    const palettes = [
      ['rgba(24,92,102,.25)','rgba(133,82,89,.07)'], ['rgba(40,82,133,.19)','rgba(130,99,71,.11)'],
      ['rgba(24,114,98,.2)','rgba(98,89,35,.08)'], ['rgba(45,104,132,.22)','rgba(112,65,151,.1)'],
      ['rgba(73,86,140,.2)','rgba(168,99,95,.10)'], ['rgba(104,80,125,.18)','rgba(67,105,116,.13)'],
      ['rgba(91,130,130,.2)','rgba(128,94,88,.09)']
    ];
    const palette = palettes[state.scene];
    const c = visualCenter();
    radialGlow(c.x, c.y, Math.max(w, h) * .72, [[0, palette[0]], [.51, 'rgba(19,35,52,.09)'], [1, 'rgba(0,0,0,0)']]);
    radialGlow(w * .20, h * .75, w * .58, [[0, palette[1]], [1, 'rgba(0,0,0,0)']]);
    for (const star of nightSky) {
      const alpha = star.a * (.62 + .38 * Math.sin(t * star.tw + star.phase));
      const drift = Math.sin(t * .13 + star.phase) * 1.6;
      fillCircle(star.x * w + drift, star.y * h, star.r * .64, star.tint ? `rgba(212,229,237,${alpha})` : `rgba(238,207,164,${alpha})`);
    }
    // Fine, almost invisible cartographic lines give the sanctuary a sense of depth.
    ctx.strokeStyle = 'rgba(173,198,202,.026)'; ctx.lineWidth = .6;
    for (let i = 0; i < 8; i++) {
      const x = (i / 7) * w;
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
    }
    for (let i = 0; i < 7; i++) {
      const y = (i / 6) * h;
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
    }
  }
  function drawRipples() {
    const w = W(), h = H();
    state.ripples = state.ripples.filter(r => state.elapsed - r.start < 3100);
    for (const p of state.ripples) {
      const age = (state.elapsed - p.start) / 3100;
      const radius = ease(age) * Math.min(w, h) * .45 * p.strength;
      ctx.beginPath(); ctx.ellipse(p.x * w, p.y * h, radius, radius * .84, 0, 0, TAU);
      ctx.strokeStyle = `rgba(170,227,224,${(1 - age) * .31})`;
      ctx.lineWidth = .75; ctx.stroke();
      if (age < .5) fillCircle(p.x * w, p.y * h, 2.5 * (1 - age), `rgba(245,215,172,${1 - age * 1.5})`);
    }
  }

  function drawBreath(t) {
    const { x, y, r } = visualCenter();
    const cycle = Math.sin(t * .63 - 1.2);
    const boost = state.pulse;
    const breatheScale = 1 + cycle * .075 + boost * .18;
    const size = r * 1.2 * breatheScale;
    radialGlow(x, y, size * 1.25, [[0, 'rgba(91,203,195,.14)'], [.34, 'rgba(57,128,138,.1)'], [1, 'rgba(0,0,0,0)']]);
    ctx.save(); ctx.translate(x, y); ctx.globalCompositeOperation = 'screen';
    // Glass filaments: a living sea anemone rather than a conventional particle sphere.
    for (let i = 0; i < 158; i++) {
      const a = i / 158 * TAU;
      const fl = Math.sin(a * 8 + t * .23) * .06;
      const reach = size * (.79 + .16 * Math.sin(i * 4.174 + t * .31));
      const inner = size * (.125 + .05 * Math.sin(i * 5.3 + t * .2));
      const bend = .37 * Math.sin(a * 5 + t * .42) + fl;
      const x0 = Math.cos(a + t * .045) * inner, y0 = Math.sin(a + t * .045) * inner * .72;
      const x1 = Math.cos(a + bend) * reach, y1 = Math.sin(a + bend) * reach * .77;
      const cpX = Math.cos(a + bend * 1.7 + .23) * reach * .65;
      const cpY = Math.sin(a + bend * 1.7 + .23) * reach * .62;
      ctx.beginPath(); ctx.moveTo(x0, y0); ctx.quadraticCurveTo(cpX, cpY, x1, y1);
      const alpha = .065 + .22 * Math.abs(Math.sin(i * .375 + t * .1));
      ctx.strokeStyle = i % 5 ? `rgba(129,220,215,${alpha})` : `rgba(245,190,138,${alpha * 1.25})`;
      ctx.lineWidth = .45 + (i % 7 === 0 ? .72 : .1); ctx.stroke();
    }
    for (let ring = 0; ring < 9; ring++) {
      ctx.beginPath();
      ctx.ellipse(0, 0, size * (.23 + ring * .065), size * (.16 + ring * .05), ring * .17 + t * .015, .2 + ring * .19, TAU - ring * .08);
      ctx.strokeStyle = `rgba(${ring % 3 ? '135,219,215' : '239,194,147'},${.035 + .085 * (9 - ring) / 9})`;
      ctx.lineWidth = .55; ctx.stroke();
    }
    for (let i = 0; i < waterDust.length; i++) {
      const p = waterDust[i], a = p.a + t * (.024 + p.rate * .04);
      const radius = size * p.ring * (1 + .04 * Math.sin(t + p.phase));
      const wobble = .15 * Math.sin(7 * a + p.phase + t * .38);
      const px = Math.cos(a + wobble) * radius, py = Math.sin(a + wobble) * radius * .79;
      const alpha = .14 + .39 * Math.abs(Math.sin(t * p.rate + p.phase));
      fillCircle(px, py, p.size * .7, i % 8 ? `rgba(154,230,223,${alpha})` : `rgba(247,200,155,${alpha})`);
    }
    ctx.restore();
    radialGlow(x, y, Math.max(14, size * .17), [[0, 'rgba(255,237,194,.8)'], [.08, 'rgba(210,244,224,.45)'], [1, 'rgba(0,0,0,0)']]);
    fillCircle(x, y, 1.9, 'rgba(255,248,230,.89)');
  }

  function drawTime(t) {
    const c = visualCenter(); const { x, y } = c;
    const r = c.r * 1.42;
    const time = state.timePhase;
    radialGlow(x, y, r * 1.3, [[0, 'rgba(66,110,161,.2)'], [.5, 'rgba(70,75,140,.06)'], [1, 'rgba(0,0,0,0)']]);
    ctx.save(); ctx.translate(x, y); ctx.globalCompositeOperation = 'screen';
    // Many different time-like trajectories coexist; there is no literal clock to obey.
    for (let k = 0; k < 16; k++) {
      const a = k / 16 * TAU;
      const rx = r * (.26 + (k % 8) * .092);
      const ry = rx * (.25 + (k % 5) * .075);
      ctx.save(); ctx.rotate(a * .73 + time * (.015 + k * .0006));
      ctx.beginPath(); ctx.ellipse(0, 0, rx, ry, 0, a + time * .095, a + time * .095 + Math.PI * 1.47);
      ctx.strokeStyle = k % 3 ? `rgba(137,197,223,${.13 + (k % 4) * .018})` : 'rgba(241,194,148,.27)';
      ctx.lineWidth = k % 4 === 0 ? 1.4 : .75; ctx.stroke();
      ctx.restore();
    }
    // Tidal ribbons circle inside the rings and escape into a wider orbit.
    for (let lane = 0; lane < 5; lane++) {
      ctx.beginPath();
      for (let i = 0; i <= 480; i++) {
        const p = i / 480, angle = p * TAU * (2 + lane * .2) + time * (.18 + lane * .018);
        const radius = r * (.18 + p * .64) * (1 + .06 * Math.sin(p * TAU * 8 + time * .36 + lane));
        const px = Math.cos(angle) * radius;
        const py = Math.sin(angle + lane * .12) * radius * (.29 + lane * .09);
        if (!i) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.strokeStyle = lane % 2 ? 'rgba(253,192,133,.20)' : 'rgba(141,217,226,.16)';
      ctx.lineWidth = .75; ctx.stroke();
    }
    for (let i = 0; i < 440; i++) {
      const p = waterDust[i], a = p.a + time * p.rate * .13;
      const rr = r * (.18 + p.ring * .76);
      const px = Math.cos(a) * rr, py = Math.sin(a) * rr * (.34 + .3 * Math.sin(p.phase));
      const alpha = .13 + .5 * (Math.sin(time * .2 + p.phase) ** 2);
      fillCircle(px, py, p.size * .64, i % 7 ? `rgba(146,205,225,${alpha})` : `rgba(255,197,137,${alpha})`);
    }
    ctx.restore();
    radialGlow(x, y, r * .15, [[0, 'rgba(253,229,184,.7)'], [1, 'rgba(0,0,0,0)']]);
    fillCircle(x, y, 2.5, 'rgba(250,234,210,.94)');
    // An orbital tick, hinting at felt rather than measured duration.
    ctx.strokeStyle = 'rgba(234,213,184,.14)'; ctx.lineWidth = .65;
    ctx.beginPath(); ctx.arc(x, y, r * .9, 0, TAU); ctx.stroke();
    const angle = time * .13;
    fillCircle(x + Math.cos(angle) * r * .9, y + Math.sin(angle) * r * .9, 3.1, 'rgba(244,216,169,.85)');
  }

  function drawLife(t) {
    const c = visualCenter();
    radialGlow(c.x, c.y * 1.15, c.r * 1.65, [[0, 'rgba(45,126,105,.14)'], [.5, 'rgba(28,74,64,.05)'], [1, 'rgba(0,0,0,0)']]);
    ctx.globalCompositeOperation = 'screen';
    // Mycelium / hidden growth underneath the visible plants.
    const floorY = H() * .82;
    for (let j = 0; j < 46; j++) {
      const a = j * .39;
      ctx.beginPath();
      ctx.moveTo(c.x + Math.sin(a) * 20, floorY);
      ctx.bezierCurveTo(c.x + Math.cos(a * 3) * W() * .13, floorY + 26,
        c.x + Math.sin(a * 2) * W() * .31, floorY + 42,
        c.x + Math.sin(a * 1.73) * W() * .4, floorY + 75);
      ctx.strokeStyle = `rgba(93,187,145,${.018 + .035 * Math.abs(Math.sin(j * 2.12))})`;
      ctx.lineWidth = .6; ctx.stroke();
    }
    state.plants.forEach(plant => drawPlant(plant, t));
    for (let i = 0; i < 230; i++) {
      const p = waterDust[i];
      const px = c.x + Math.cos(p.a + t * .12 * p.rate) * c.r * p.ring * 1.38;
      const py = H() * .72 + Math.sin(p.phase + t * p.rate * .15) * c.r * .67;
      fillCircle(px, py, p.size * .65, `rgba(138,234,181,${.1 + .25 * Math.abs(Math.sin(t + p.phase))})`);
    }
    ctx.globalCompositeOperation = 'source-over';
  }
  function drawPlant(plant, t) {
    const growth = clamp((state.elapsed - plant.start) / 5200, 0, 1);
    const x = plant.x * W(), y = plant.y * H();
    const scale = (W() < 800 ? Math.min(H() / 760, W() / 390) * .92 : Math.min(H() / 760, W() / 950) * 1.15) * plant.size;
    const depthMax = 8;
    ctx.save(); ctx.translate(x, y); ctx.scale(scale, scale);
    const sway = Math.sin(t * .58 + plant.kind) * .043;
    const branch = (bx, by, len, angle, depth, n) => {
      const step = depthMax - depth;
      const visible = clamp((growth * (depthMax + .65) - step) / .88, 0, 1);
      if (visible <= 0) return;
      const ang = angle + Math.sin(t * .55 + n + plant.kind) * .015 * (depthMax - depth);
      const ex = bx + Math.cos(ang) * len * visible;
      const ey = by + Math.sin(ang) * len * visible;
      const alpha = .27 + .51 * (depth / depthMax);
      ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(ex, ey);
      ctx.strokeStyle = depth > 3 ? `rgba(162,231,192,${alpha})` : `rgba(221,192,134,${alpha})`;
      ctx.lineWidth = Math.max(.45, depth * .36); ctx.lineCap = 'round'; ctx.stroke();
      if (depth <= 1 && visible > .8) {
        const glint = .42 + .35 * Math.sin(t * 1.3 + n * 5);
        fillCircle(ex, ey, 1.4 + 1.4 * glint, `rgba(183,255,218,${glint})`);
        if (n % 3 === 0) fillCircle(ex + Math.sin(t + n) * 2, ey, 3, `rgba(171,248,205,${glint * .13})`);
      }
      if (depth <= 0 || visible < .95) return;
      const twist = .14 * Math.sin(n * 7.2 + plant.kind);
      const split = .29 + .11 * Math.sin(plant.kind * 3 + n * .7);
      branch(ex, ey, len * (.74 + Math.sin(n) * .03), ang - split + twist, depth - 1, n * 2 + 1);
      branch(ex, ey, len * (.71 + Math.cos(n) * .04), ang + split + twist, depth - 1, n * 2 + 2);
    };
    branch(0, 0, 70, -Math.PI / 2 + sway + plant.tilt, depthMax, 1);
    fillCircle(0, 0, 2.3, 'rgba(255,222,164,.88)');
    ctx.restore();
  }

  function drawPerception(t) {
    const c = visualCenter();
    const mx = state.pointer.x * W(), my = state.pointer.y * H();
    radialGlow(mx, my, c.r * 1.26, [[0, 'rgba(95,179,207,.16)'], [.42, 'rgba(100,115,182,.06)'], [1, 'rgba(0,0,0,0)']]);
    const maxRadius = c.r * 1.27;
    const step = W() < 800 ? 26 : 32;
    ctx.globalCompositeOperation = 'screen';
    // A latent lattice only reveals its delicate geometry in the observer's focus.
    for (let yy = c.y - maxRadius; yy < c.y + maxRadius; yy += step) {
      for (let xx = c.x - maxRadius * 1.16; xx < c.x + maxRadius * 1.16; xx += step) {
        const dCenter = Math.hypot((xx - c.x) * .89, yy - c.y);
        if (dCenter > maxRadius) continue;
        const d = Math.hypot(xx - mx, yy - my);
        const focus = clamp(1 - d / (c.r * .94), 0, 1);
        const wave = Math.sin(xx * .015 + t * .34) * Math.cos(yy * .019 - t * .29);
        const shift = (state.inverted ? -1 : 1);
        const bend = (wave * 12 + focus * 24 * Math.sin(yy * .012 + t)) * shift;
        const nx = xx + bend, ny = yy + wave * 13 * shift;
        const alpha = .055 + focus * .64;
        fillCircle(nx, ny, .65 + focus * 2.05, focus > .56 ? `rgba(247,214,172,${alpha})` : `rgba(132,212,228,${alpha})`);
        if (focus > .27) {
          ctx.beginPath(); ctx.moveTo(nx, ny);
          ctx.lineTo(nx + Math.cos(wave * 3 + (state.inverted ? Math.PI / 2 : 0)) * step * focus * .68,
            ny + Math.sin(wave * 3) * step * focus * .68);
          ctx.strokeStyle = `rgba(132,209,224,${focus * .26})`; ctx.lineWidth = .6; ctx.stroke();
        }
      }
    }
    // A soft focus reticle, visibly pulled toward the observer.
    ctx.beginPath(); ctx.arc(mx, my, c.r * .53 + Math.sin(t * 1.1) * 3, 0, TAU);
    ctx.strokeStyle = 'rgba(226,221,190,.18)'; ctx.lineWidth = .9; ctx.stroke();
    ctx.beginPath(); ctx.arc(mx, my, c.r * .23, .3 + t * .12, Math.PI * 1.38 + t * .12);
    ctx.strokeStyle = 'rgba(247,220,178,.34)'; ctx.stroke();
    fillCircle(mx, my, 2.4, 'rgba(254,239,206,.95)');
    for (let i = 0; i < 10; i++) {
      const a = i / 10 * TAU + .23;
      const px = c.x + Math.cos(a) * c.r * .83, py = c.y + Math.sin(a) * c.r * .8;
      const proximity = clamp(1 - Math.hypot(px - mx, py - my) / (c.r * .78), 0, 1);
      if (proximity < .25) continue;
      ctx.font = `${10 + Math.round(proximity * 3)}px serif`;
      ctx.textAlign = 'center'; ctx.fillStyle = `rgba(235,225,210,${proximity * .36})`;
      ctx.fillText(perceptionWords[i], px, py);
    }
    ctx.textAlign = 'left'; ctx.globalCompositeOperation = 'source-over';
  }

  function nodePoint(n, t) {
    const c = visualCenter();
    return { x: c.x + n.x * c.r * 1.19 + Math.sin(t * .16 + n.phase) * 8,
      y: c.y + n.y * c.r * 1.03 + Math.cos(t * .11 + n.phase) * 5 };
  }
  function drawConnection(t) {
    const c = visualCenter();
    radialGlow(c.x, c.y, c.r * 1.65, [[0, 'rgba(92,119,178,.2)'], [.54, 'rgba(99,74,136,.06)'], [1, 'rgba(0,0,0,0)']]);
    ctx.globalCompositeOperation = 'screen';
    // Background barely-there interdependence.
    for (let i = 0; i < nodes.length; i++) {
      const a = nodes[i], ap = nodePoint(a, t);
      for (let j = i + 1; j < nodes.length; j++) {
        const b = nodes[j]; const dx = b.x - a.x, dy = b.y - a.y;
        const dist = Math.hypot(dx, dy);
        if (dist > .34 || dist < .09 || (i + j) % 5) continue;
        const bp = nodePoint(b, t);
        ctx.beginPath(); ctx.moveTo(ap.x, ap.y); ctx.lineTo(bp.x, bp.y);
        ctx.strokeStyle = `rgba(119,163,187,${(.34 - dist) * .21})`;
        ctx.lineWidth = .55; ctx.stroke();
      }
    }
    for (const edge of state.links) {
      const ap = nodePoint(nodes[edge.a], t), bp = nodePoint(nodes[edge.b], t);
      const progress = ease((state.elapsed - edge.start) / 1700);
      const dx = bp.x - ap.x, dy = bp.y - ap.y;
      const endX = ap.x + dx * progress, endY = ap.y + dy * progress;
      ctx.beginPath(); ctx.moveTo(ap.x, ap.y); ctx.lineTo(endX, endY);
      ctx.strokeStyle = 'rgba(135,226,221,.65)'; ctx.lineWidth = 1.1; ctx.stroke();
      ctx.beginPath(); ctx.moveTo(ap.x, ap.y); ctx.lineTo(endX, endY);
      ctx.strokeStyle = 'rgba(160,244,237,.18)'; ctx.lineWidth = 4; ctx.stroke();
      if (progress > .98) {
        const pos = (t * .22 + edge.a * .069) % 1;
        fillCircle(lerp(ap.x, bp.x, pos), lerp(ap.y, bp.y, pos), 2.2, 'rgba(252,222,167,.8)');
      }
    }
    nodes.forEach(n => {
      const p = nodePoint(n, t);
      const glow = .49 + .45 * Math.abs(Math.sin(t * .78 + n.phase));
      const selected = state.selectedNode === n.id;
      if (selected) {
        ctx.beginPath(); ctx.arc(p.x, p.y, 12 + Math.sin(t * 2) * 1.8, 0, TAU);
        ctx.strokeStyle = 'rgba(247,211,168,.63)'; ctx.lineWidth = 1; ctx.stroke();
      }
      fillCircle(p.x, p.y, n.size * (selected ? 2.2 : 1.0), `rgba(${n.id % 7 ? '162,214,223' : '249,204,155'},${glow})`);
      if (n.id % 11 === 0) fillCircle(p.x, p.y, 5, `rgba(165,224,223,${glow * .095})`);
    });
    ctx.globalCompositeOperation = 'source-over';
  }

  function drawRelease(t) {
    const c = visualCenter();
    const { x, y } = c;
    radialGlow(x, y, c.r * 1.7, [[0, 'rgba(135,93,154,.14)'], [.49, 'rgba(91,111,150,.06)'], [1, 'rgba(0,0,0,0)']]);
    ctx.save(); ctx.translate(x, y); ctx.globalCompositeOperation = 'screen';
    for (let k = 0; k < 8; k++) {
      const r = c.r * (.19 + k * .095);
      ctx.beginPath(); ctx.ellipse(0, 0, r, r * (.5 + k * .032), t * .022 + k * .16, .3 + k * .21, Math.PI * 1.8 + k * .17);
      ctx.strokeStyle = k % 2 ? `rgba(166,142,209,${.09 + .08 * Math.sin(t + k) ** 2})` : `rgba(178,217,222,${.08 + .06 * Math.sin(t + k) ** 2})`;
      ctx.lineWidth = .72; ctx.stroke();
    }
    for (let i = 0; i < 310; i++) {
      const p = waterDust[i];
      const a = p.a + t * .09 * p.rate;
      const radius = c.r * (p.ring * .8 + .1);
      fillCircle(Math.cos(a) * radius, Math.sin(a) * radius * .75, p.size * .65,
        i % 5 ? `rgba(169,161,211,${.13 + .31 * Math.abs(Math.sin(t + p.phase))})` : 'rgba(239,194,170,.43)');
    }
    ctx.restore();
    state.released = state.released.filter(p => state.elapsed - p.birth - p.offset < 7300);
    for (const p of state.released) {
      const age = Math.max(0, state.elapsed - p.birth - p.offset);
      const frac = age / 5800;
      const dissolve = ease(frac);
      const px = p.x * W() + p.vx * age * (1 + frac * 4) * W() + Math.sin(age * .002 + p.phase) * dissolve * 27;
      const py = p.y * H() + p.vy * age * (1 + frac * 2) * H() - frac * frac * H() * .11;
      const alpha = (1 - clamp(frac, 0, 1)) * (.7 + .3 * Math.sin(age * .003 + p.phase));
      fillCircle(px, py, p.size * (1 + frac * 1.7), `rgba(${p.phase < 3 ? '255,212,177' : '157,224,223'},${alpha * .8})`);
    }
    radialGlow(x, y, c.r * .11, [[0, 'rgba(241,215,211,.55)'], [1, 'rgba(0,0,0,0)']]);
    fillCircle(x, y, 1.8, 'rgba(247,225,217,.94)');
  }

  function drawReturn(t) {
    const c = visualCenter();
    radialGlow(c.x, c.y, c.r * 1.7, [[0, 'rgba(115,172,168,.18)'], [.5, 'rgba(118,117,154,.08)'], [1, 'rgba(0,0,0,0)']]);
    const counts = [1 + state.breathCount, 1 + state.seedCount, 1 + state.focusCount, 1 + state.linkCount, 1 + state.releaseCount, 1 + state.actionCount, 1 + (randomSeed % 5)];
    const points = [];
    ctx.save(); ctx.translate(c.x, c.y); ctx.globalCompositeOperation = 'screen';
    for (let ring = 0; ring < 7; ring++) {
      const r = c.r * (.26 + ring * .13);
      const off = ring * .83 + Math.sin(t * .07 + ring) * .2;
      const rx = r * (ring % 2 ? .86 : 1.04), ry = r * (.28 + ring * .067);
      ctx.save(); ctx.rotate(off * .3);
      ctx.beginPath(); ctx.ellipse(0, 0, rx, ry, 0, 0, TAU);
      ctx.strokeStyle = `rgba(${ring % 3 ? '147,219,216' : '241,199,158'},${.09 + counts[ring] * .006})`;
      ctx.lineWidth = .7 + (counts[ring] % 4) * .2; ctx.stroke();
      ctx.restore();
      const theta = t * (.04 + ring * .006) * (ring % 2 ? -1 : 1) + ring * 2.39996 + counts[ring] * .37;
      const x = Math.cos(theta) * r * .96, y = Math.sin(theta + off) * r * .65;
      points.push({ x, y, r: 2 + Math.min(counts[ring], 14) * .16 });
    }
    for (let i = 0; i < points.length; i++) for (let j = i + 1; j < points.length; j++) {
      if ((i + j) % 3 === 1) continue;
      const a = points[i], b = points[j];
      ctx.beginPath(); ctx.moveTo(a.x, a.y);
      ctx.bezierCurveTo(a.x * .5, a.y * -.5, b.x * -.35, b.y * .48, b.x, b.y);
      ctx.strokeStyle = `rgba(144,225,218,${.09 + .11 * Math.sin(t * .3 + i + j) ** 2})`;
      ctx.lineWidth = .75; ctx.stroke();
    }
    for (const p of points) {
      fillCircle(p.x, p.y, p.r * 4, 'rgba(151,225,218,.07)');
      fillCircle(p.x, p.y, p.r, 'rgba(242,222,185,.85)');
    }
    for (let i = 0; i < 750; i++) {
      const p = waterDust[i % waterDust.length];
      const angle = p.a * 2.13 + i * .043 + t * (.008 + p.rate * .011);
      const radius = c.r * p.ring * (1.35 + .16 * Math.sin(t * .2 + p.phase));
      const x = Math.cos(angle) * radius, y = Math.sin(angle) * radius * .68;
      fillCircle(x, y, p.size * .55, i % 7 ? `rgba(178,233,225,${.14 + .37 * p.ring})` : 'rgba(244,204,159,.51)');
    }
    ctx.restore();
    radialGlow(c.x, c.y, c.r * .23, [[0, 'rgba(250,222,177,.35)'], [1, 'rgba(0,0,0,0)']]);
  }

  let animationId;
  function frame(now) {
    const delta = state.lastFrame ? clamp(now - state.lastFrame, 0, 56) : 16;
    state.lastFrame = now;
    // When motion is reduced, keep a still living image rather than removing the image.
    const dt = state.prefersReduced ? delta * .13 : delta;
    state.elapsed += dt;
    state.t += dt / 1000;
    state.timePhase += state.scene === 1 && state.timePaused ? 0 : dt / 1000 * state.rate;
    state.pulse = Math.max(0, state.pulse - dt / 1850);
    state.pointer.x = lerp(state.pointer.x, state.pointer.tx, .09);
    state.pointer.y = lerp(state.pointer.y, state.pointer.ty, .09);
    const t = state.t;
    drawEnvironment(t);
    switch (state.scene) {
      case 0: drawBreath(t); break;
      case 1: drawTime(t); break;
      case 2: drawLife(t); break;
      case 3: drawPerception(t); break;
      case 4: drawConnection(t); break;
      case 5: drawRelease(t); break;
      case 6: drawReturn(t); break;
    }
    drawRipples();
    // Slow, transparent phase veil for moving between rooms.
    if (state.sceneTransition > 0) {
      ctx.fillStyle = `rgba(5,9,17,${state.sceneTransition * .56})`;
      ctx.fillRect(0, 0, W(), H());
      state.sceneTransition = Math.max(0, state.sceneTransition - dt / 590);
    }
    animationId = requestAnimationFrame(frame);
  }

  function pointInput(event) {
    if (state.menuOpen || state.aboutOpen) return;
    const target = event.target;
    if (target && target.closest && target.closest('button, input, form, a, nav, header, footer, .interaction-area, .stage-copy')) return;
    const x = clamp(event.clientX / W(), 0, 1), y = clamp(event.clientY / H(), 0, 1);
    state.pointer.tx = x; state.pointer.ty = y;
    state.pointer.active = true;
  }
  function handleCanvasAction(event) {
    if (state.menuOpen || state.aboutOpen || event.button > 0) return;
    const target = event.target;
    if (target && target.closest && target.closest('button, input, form, a, nav, header, footer, .interaction-area, .stage-copy')) return;
    const x = clamp(event.clientX / W(), 0, 1), y = clamp(event.clientY / H(), 0, 1);
    if (state.scene === 0) breathe();
    else if (state.scene === 1) { state.timePaused = !state.timePaused; const pauseBtn = $('timePause'); if (pauseBtn) pauseBtn.textContent = state.timePaused ? '다시 흐르게' : '잠시 멈추기'; nextQuote(); addRipple(x, y); }
    else if (state.scene === 2) plantSeed(x, y);
    else if (state.scene === 3) { state.pointer.tx = x; state.pointer.ty = y; state.focusCount++; state.actionCount++; addRipple(x, y); nextQuote(); }
    else if (state.scene === 4) {
      let nearest = -1, distance = Infinity;
      nodes.forEach((n, i) => { const p = nodePoint(n, state.t); const d = Math.hypot(p.x - event.clientX, p.y - event.clientY); if (d < distance) { distance = d; nearest = i; } });
      if (distance > Math.max(46, Math.min(W(), H()) * .1)) { showToast('빛나는 별 가까이를 선택해 보세요.'); return; }
      if (state.selectedNode === null) {
        state.selectedNode = nearest; addRipple(x, y, .55); subtleSound(350);
        showToast('첫 번째 별이 선택되었습니다. 다른 별을 찾아보세요.');
      } else if (state.selectedNode === nearest) {
        state.selectedNode = null; showToast('선택을 풀었습니다.');
      } else { connectNodes(state.selectedNode, nearest); state.selectedNode = null; }
    }
    else if (state.scene === 5) { state.pulse = 1; addRipple(x, y); }
    else if (state.scene === 6) { addRipple(x, y); nextQuote(); }
  }

  // Initialize every button/keyboard path explicitly, avoiding inert controls.
  document.querySelectorAll('.rail-button').forEach(btn => btn.addEventListener('click', () => changeScene(Number(btn.dataset.scene))));
  const mobileScenes = $('mobileScenes');
  roomData.forEach((room, i) => {
    const btn = document.createElement('button');
    btn.type = 'button'; btn.className = 'mobile-scene' + (i === 0 ? ' active' : ''); btn.dataset.scene = String(i);
    btn.innerHTML = `<span class="m-number">${String(i + 1).padStart(2, '0')}</span><span>${escapeAttr(room.name)}</span><span class="m-en">${escapeAttr(room.en.split(' / ')[0])}</span>`;
    btn.addEventListener('click', () => changeScene(i));
    mobileScenes.appendChild(btn);
  });
  $('brand').addEventListener('click', () => changeScene(0));
  $('prevBtn').addEventListener('click', () => changeScene(state.scene - 1));
  $('nextBtn').addEventListener('click', () => changeScene(state.scene + 1));
  $('menuBtn').addEventListener('click', toggleMenu);
  $('aboutBtn').addEventListener('click', openAbout);
  $('closeAbout').addEventListener('click', closeAbout);
  $('aboutContinue').addEventListener('click', closeAbout);
  $('aboutOverlay').addEventListener('click', e => { if (e.target === $('aboutOverlay')) closeAbout(); });
  $('soundBtn').addEventListener('click', toggleSound);
  $('fullscreenBtn').addEventListener('click', () => {
    if (!document.fullscreenElement) {
      const req = document.documentElement.requestFullscreen;
      if (req) req.call(document.documentElement).catch(() => showToast('전체 화면 모드를 시작할 수 없습니다.'));
      else showToast('현재 브라우저는 전체 화면을 지원하지 않습니다.');
    } else if (document.exitFullscreen) document.exitFullscreen();
  });
  window.addEventListener('resize', sizeWorld, { passive: true });
  window.addEventListener('pointermove', pointInput, { passive: true });
  window.addEventListener('pointerdown', handleCanvasAction, { passive: true });
  window.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      if (state.aboutOpen) closeAbout();
      else if (state.menuOpen) closeMenu();
      return;
    }
    if (state.aboutOpen || state.menuOpen || /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName || '')) return;
    if (e.key === 'ArrowLeft') { e.preventDefault(); changeScene(state.scene - 1); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); changeScene(state.scene + 1); }
    else if (/^[1-7]$/.test(e.key)) changeScene(Number(e.key) - 1);
    else if (e.code === 'Space' && document.activeElement === document.body) {
      e.preventDefault(); if (state.scene === 0) breathe(); else if (state.scene === 2) plantSeed(.68, .73);
    }
  });
  const clockUpdate = () => {
    const d = new Date();
    $('localClock').textContent = `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
  };
  clockUpdate(); setInterval(clockUpdate, 20000);
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) state.lastFrame = 0;
    if (state.audio) {
      if (document.hidden) state.audio.ctx.suspend();
      else if (state.sound) state.audio.ctx.resume();
    }
  });
  controlsForScene();
  sizeWorld();
  animationId = requestAnimationFrame(frame);
  // Developer check: expose only non-sensitive runtime diagnostics, no data collection.
  window.SAI = Object.freeze({ version: '1.0.0', getScene: () => state.scene, getStats: () => ({ breaths: state.breathCount, seeds: state.seedCount, focus: state.focusCount, links: state.linkCount, releases: state.releaseCount }) });
})();
